function check([operations, args], actual, expected) {
  const [radius, xCenter, yCenter] = args[0];
  if (!Array.isArray(actual) || actual.length !== operations.length || actual[0] !== null) return false;
  // A point on the edge may land a rounding error outside it.
  const slack = 1e-9 * radius + 1e-14 * (Math.abs(xCenter) + Math.abs(yCenter));
  const rings = new Array(4).fill(0), slices = new Array(8).fill(0), cells = new Array(32).fill(0);
  for (let i = 1; i < actual.length; i++) {
    const point = actual[i];
    if (!Array.isArray(point) || point.length !== 2 || !point.every(Number.isFinite)) return false;
    const dx = point[0] - xCenter, dy = point[1] - yCenter;
    if (Math.hypot(dx, dy) > radius + slack) return false;
    // Four rings of equal area (by squared distance) and eight equal slices of angle.
    const ring = Math.min(3, Math.floor(4 * (dx * dx + dy * dy) / (radius * radius)));
    const slice = Math.min(7, Math.floor(8 * (Math.atan2(dy, dx) + Math.PI) / (2 * Math.PI)));
    rings[ring]++;
    slices[slice]++;
    cells[ring * 8 + slice]++;
  }
  const calls = actual.length - 1;
  if (calls < 40) return true;
  // A fair count over n tries with chance p stays within 5.5 standard deviations (+3 slack).
  const fair = (seen, p) => Math.abs(seen - calls * p) <= 5.5 * Math.sqrt(calls * p * (1 - p)) + 3;
  if (!rings.every(c => fair(c, 1 / 4)) || !slices.every(c => fair(c, 1 / 8))) return false;
  if (calls < 160) return true;
  const mean = calls / 32;
  const chi = cells.reduce((sum, c) => sum + (c - mean) ** 2 / mean, 0);
  return chi <= 31 + 6 * Math.sqrt(62) + 8;
}

validator:
function validate([operations, args]) {
  if (operations[0] !== 'Solution' || !Array.isArray(args[0]) || args[0].length !== 3) return 'The first call is Solution(radius, x_center, y_center).';
  const [radius, xCenter, yCenter] = args[0];
  if (![radius, xCenter, yCenter].every(Number.isFinite)) return 'radius, x_center and y_center are numbers.';
  if (radius <= 0 || radius > 1e8) return 'radius is above 0 and at most 10^8.';
  if (Math.abs(xCenter) > 1e7 || Math.abs(yCenter) > 1e7) return 'x_center and y_center are between -10^7 and 10^7.';
  if (operations.slice(1).some(op => op !== 'randPoint')) return 'After the constructor, only randPoint is called.';
  if (operations.length - 1 > 30000) return 'At most 3 * 10^4 calls are made to randPoint.';
  return null;
}

