class Solution {
  constructor(radius, x_center, y_center) {
    this.radius = radius;
    this.xCenter = x_center;
    this.yCenter = y_center;
  }

  randPoint() {
    const angle = 2 * Math.PI * Math.random();
    const distance = this.radius * Math.sqrt(Math.random());
    const x = this.xCenter + distance * Math.cos(angle);
    const y = this.yCenter + distance * Math.sin(angle);
    return [x, y];
  }
}

