class Solution {
  constructor(radius, x_center, y_center) {
    this.r = radius;
    this.cx = x_center;
    this.cy = y_center;
  }
  randPoint() {
    // Throw darts at the bounding square and keep the first one that lands in the circle.
    for (;;) {
      const dx = (2 * Math.random() - 1) * this.r;
      const dy = (2 * Math.random() - 1) * this.r;
      if (dx * dx + dy * dy <= this.r * this.r) return [this.cx + dx, this.cy + dy];
    }
  }
}

