function generate(rand, size) {
  const large = size === 'large';
  const pick = list => list[Math.floor(rand() * list.length)];
  // Radii from tiny to the maximum, rounded to a few digits so the JSON stays readable.
  const radius = rand() < 0.3 ? pick([1, 0.5, 0.01, 2.5, 1e8]) : Math.min(1e8, Number((10 ** (rand() * 10 - 2)).toPrecision(4)));
  const center = () => rand() < 0.25 ? pick([-1e7, 1e7, 0]) : Math.round((2 * rand() - 1) * (rand() < 0.5 ? 10 : 1e7) * 100) / 100;
  const count = large ? 499 : 1 + Math.floor(rand() * 200);
  return [["Solution", ...Array(count).fill("randPoint")], [[radius, center(), center()], ...Array.from({ length: count }, () => [])]];
}
